import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiItem","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/index.md","filePath":"modules/item/index.md","lastUpdated":0}`),a={name:`modules/item/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiitem" tabindex="-1">EmakiItem <a class="header-anchor" href="#emakiitem" aria-label="Permalink to “EmakiItem”">​</a></h1><p>EmakiItem 是轻量自定义物品模块，提供稳定物品 ID、基础属性、套装、触发动作、自动更新与 PlaceholderAPI 支持。它适合作为装备成长线的起点：先生成一件有稳定 ID 的装备，再交给 Forge、Strengthen、Gem、Attribute 和 Skills 继续扩展。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.8.0</code></td></tr><tr><td>主命令</td><td><code>/emakiitem</code></td></tr><tr><td>别名</td><td><code>/ei</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiAttribute、EmakiSkills、MythicMobs、PlaceholderAPI</td></tr><tr><td>权限节点</td><td><code>emakiitem.use</code>、<code>emakiitem.give</code>、<code>emakiitem.browse</code>、<code>emakiitem.inspect</code>、<code>emakiitem.update</code>、<code>emakiitem.reload</code>、<code>emakiitem.debug</code>、<code>emakiitem.admin</code></td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>列出与发放物品、检查手持物与组件、刷新物品与套装、重载与调试。</td></tr><tr><td><a href="./definitions.html">物品定义与套装</a></td><td><code>items/*.yml</code> 与 <code>sets/*.yml</code> 的字段、物品 ID 到 ItemStack 的生成规则。</td></tr><tr><td><a href="./browser.html">物品浏览 GUI</a></td><td><code>/ei browse</code> 的两级浏览界面、<code>pack.yml</code> 物品包元数据与槽位类型。</td></tr><tr><td><a href="./triggers.html">触发器</a></td><td>交互、攻击、投射物、方块、丢弃等事件中执行动作。</td></tr><tr><td><a href="./update.html">物品更新策略</a></td><td>物品定义变更后把玩家手上的旧物品更新到新版本。</td></tr><tr><td><a href="./repair.html">物品修复系统</a></td><td>耐久归零后的禁用状态与材料/货币修复流程。</td></tr><tr><td><a href="./integration.html">跨模块集成</a></td><td>被 Attribute、Forge、Strengthen、Gem、Skills、Cooking 引用时的物品来源写法。</td></tr><tr><td><a href="./mythic.html">MythicMobs 集成</a></td><td>在 MythicMobs 的 <code>Drops</code> 中掉落 EmakiItem 物品。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>主手物品更新、重绘、修复、耐久与原版 Data Component 动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>通过 <code>EmakiItemApi</code> 创建、识别与查询物品。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>物品流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>稳定物品 ID</td><td>用配置 ID 标识物品，不依赖显示名。</td></tr><tr><td>物品组件</td><td>配置材质、名称、Lore、模型、附魔、flags、耐久等。</td></tr><tr><td>属性写入</td><td>可向 Attribute 提供属性 payload。</td></tr><tr><td>技能绑定</td><td>可让物品提供技能或技能解锁信息。</td></tr><tr><td>套装系统</td><td>根据装备件数触发属性、技能或 Lore。</td></tr><tr><td>触发器</td><td>在交互、攻击、投射物、方块、丢弃等事件中执行动作。</td></tr><tr><td>自动更新</td><td>玩家登录、切换手持、点击背包、拾取等场景刷新物品。</td></tr><tr><td>修复系统</td><td>耐久归零后进入禁用状态，可用材料或货币修复。</td></tr><tr><td>浏览界面</td><td>两级 GUI 按物品包浏览全部物品，可直接取出。</td></tr><tr><td>ID alias 与迁移</td><td>支持物品 ID 改名映射，并可批量迁移配置与玩家背包。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiItem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── id_aliases.yml</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── sets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>items/</code> 定义物品，<code>sets/</code> 定义套装，<code>gui/</code> 存放修复界面与两级浏览界面模板（<code>repair_gui.yml</code>、<code>pack_browser_gui.yml</code>、<code>item_browser_gui.yml</code>），<code>id_aliases.yml</code> 保存物品 ID 改名映射。</p><p><code>items/</code> 的每个子目录都是一个物品包，可放一份 <code>pack.yml</code> 定义它在浏览界面里的图标，详见<a href="./browser.html">物品浏览 GUI</a>。</p><h2 id="主配置" tabindex="-1">主配置 <a class="header-anchor" href="#主配置" aria-label="Permalink to “主配置”">​</a></h2><p><code>config.yml</code> 只包含全局设置，物品行为写在各自的定义文件里。</p><table tabindex="0"><thead><tr><th>配置键</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>当前模块版本</td><td>默认配置结构标识，不建议手动修改。</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>语言文件 ID，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>是否释放 <code>items/</code>、<code>sets/</code> 等默认示例数据。config.yml 与语言文件不受此项控制。</td></tr><tr><td><code>data_directories.max_depth</code></td><td>int</td><td><code>2</code></td><td><code>items/</code> 与 <code>sets/</code> 的子目录扫描层数上限（含数据目录本身）。<code>1</code> 只读根目录，<code>2</code> 允许一层子目录，<code>3</code> 允许两层。超限子目录会被跳过并输出控制台警告，最小值为 <code>1</code>。</td></tr><tr><td><code>set_bonus.enabled</code></td><td>boolean</td><td><code>true</code></td><td>是否启用套装加成系统。</td></tr><tr><td><code>set_bonus.refresh_triggers.join</code></td><td>boolean</td><td><code>true</code></td><td>玩家进服时刷新套装状态。</td></tr><tr><td><code>set_bonus.refresh_triggers.held_change</code></td><td>boolean</td><td><code>true</code></td><td>切换手持物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_click</code></td><td>boolean</td><td><code>true</code></td><td>点击背包时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_drag</code></td><td>boolean</td><td><code>true</code></td><td>拖拽物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.pickup</code></td><td>boolean</td><td><code>true</code></td><td>拾取物品时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.interact</code></td><td>boolean</td><td><code>true</code></td><td>交互时刷新。</td></tr><tr><td><code>set_bonus.refresh_triggers.command</code></td><td>boolean</td><td><code>true</code></td><td>执行相关命令时允许刷新。</td></tr><tr><td><code>mythicmobs.enabled</code></td><td>boolean</td><td><code>true</code></td><td>MythicMobs 集成总开关。</td></tr><tr><td><code>mythicmobs.drops.enabled</code></td><td>boolean</td><td><code>true</code></td><td>是否注册 MythicMobs 自定义 Drop。</td></tr><tr><td><code>mythicmobs.drops.names</code></td><td>list</td><td><code>emakiitem</code>、<code>ei_item</code></td><td>可识别的 Drop 名称；为空时回退默认值。</td></tr><tr><td><code>item_state.clamp</code></td><td>boolean</td><td><code>true</code></td><td>是否按 <code>fields</code> 声明的 min/max 钳制写入值。关闭后只保留溢出保护。</td></tr><tr><td><code>item_state.fill_defaults</code></td><td>boolean</td><td><code>true</code></td><td><code>add</code> 操作在字段缺失时是否用 <code>fields</code> 的 default 作为起始值。关闭后字段缺失直接拒绝。</td></tr><tr><td><code>item_state.fields</code></td><td>map</td><td><code>{}</code></td><td>字段声明，键名即状态键名。含 <code>type</code>、<code>default</code>、<code>min</code>、<code>max</code> 与 <code>thresholds</code>；只有数值类型支持 min/max 与阈值。未声明的字段不受钳制、默认值与阈值影响。</td></tr><tr><td><code>item_state.migrations</code></td><td>map</td><td><code>{}</code></td><td>按 schema 版本的迁移步骤，每步声明 <code>from</code>/<code>to</code>，可 <code>rename</code>、<code>retype</code>、<code>drop</code> 字段。留空表示不迁移。</td></tr><tr><td><code>item_state.preservation.verify_rebuild</code></td><td>boolean</td><td><code>true</code></td><td>物品 rebuild 后校验状态是否仍在，缺失时用重建前快照回填。</td></tr><tr><td><code>item_state.preservation.repair_on_pickup</code></td><td>boolean</td><td><code>false</code></td><td>拾取时修复损坏的状态元数据。</td></tr><tr><td><code>item_state.preservation.repair_on_drop</code></td><td>boolean</td><td><code>false</code></td><td>丢弃时修复损坏的状态元数据。</td></tr><tr><td><code>item_state.preservation.repair_on_trade</code></td><td>boolean</td><td><code>false</code></td><td>交易时修复损坏的状态元数据。</td></tr><tr><td><code>item_state.preservation.repair_on_container_transfer</code></td><td>boolean</td><td><code>false</code></td><td>容器转移时修复损坏的状态元数据。</td></tr><tr><td><code>item_state.preservation.repair_on_join</code></td><td>boolean</td><td><code>false</code></td><td>玩家进服时修复损坏的状态元数据。</td></tr><tr><td><code>item_state.derivation.enabled</code></td><td>boolean</td><td><code>false</code></td><td>状态变更驱动派生刷新的总开关。</td></tr><tr><td><code>item_state.derivation.refresh_lore</code></td><td>boolean</td><td><code>true</code></td><td>派生刷新时刷新套装 Lore。</td></tr><tr><td><code>item_state.derivation.refresh_attributes</code></td><td>boolean</td><td><code>true</code></td><td>派生刷新时同步属性。</td></tr><tr><td><code>item_state.derivation.scan_holder</code></td><td>boolean</td><td><code>true</code></td><td>缺少持有者信息时允许扫描在线玩家定位物品。</td></tr><tr><td><code>item_state.derivation.max_depth</code></td><td>int</td><td><code>2</code></td><td>派生刷新与阈值奖励的最大递归深度，用于阻断自触发循环。</td></tr><tr><td><code>proficiency_guard.dedupe_per_event</code></td><td>boolean</td><td><code>true</code></td><td>同一物品定义在一次事件中只派发一次。</td></tr><tr><td><code>proficiency_guard.max_dispatches_per_event</code></td><td>int</td><td><code>0</code></td><td>单次事件最多派发次数；<code>0</code> 表示不限制。</td></tr><tr><td><code>proficiency_guard.same_target_cooldown_seconds</code></td><td>int</td><td><code>0</code></td><td>对同一目标的冷却秒数；<code>0</code> 表示无冷却。</td></tr><tr><td><code>proficiency_guard.daily_soft_cap</code></td><td>int</td><td><code>0</code></td><td>每日软上限；<code>0</code> 表示无上限。计数存在内存中，按服务器本地日期跨天重置，不跨重启保留。</td></tr><tr><td><code>proficiency_guard.decay_factor</code></td><td>double</td><td><code>1.0</code></td><td>超过软上限后的递减系数，取值 (0, 1]；<code>1.0</code> 表示超限直接拒绝。</td></tr><tr><td><code>proficiency_guard.decay_minimum_ratio</code></td><td>double</td><td><code>0.0</code></td><td>递减后的最低通过概率下限，取值 [0, 1]。</td></tr><tr><td><code>proficiency_guard.guarded_triggers</code></td><td>list</td><td><code>damage_dealt</code>、<code>kill_entity</code>、<code>kill_player</code></td><td>受该段约束的触发器名单。</td></tr></tbody></table><p><code>set_bonus.refresh_triggers</code> 控制套装状态刷新；物品自动更新由物品定义的 <code>update.triggers</code> 单独控制，二者互不覆盖。</p><p><code>item_state.*</code> 作用于 <code>emaki:item_state</code> PDC 分区，由 <code>item_state_*</code> 动作段与 API 读写，全部为增量配置：不写任何内容时行为与旧版本一致。<code>proficiency_guard.*</code> 作用于 <code>damage_dealt</code>、<code>kill_entity</code>、<code>kill_player</code> 的槽位派发，除 <code>dedupe_per_event</code> 外全部默认关闭或无限。</p><h2 id="典型物品生命周期" tabindex="-1">典型物品生命周期 <a class="header-anchor" href="#典型物品生命周期" aria-label="Permalink to “典型物品生命周期”">​</a></h2><ol><li>在 <code>items/</code> 中定义物品 ID、材质、名称、Lore 和组件。</li><li>可选写入 Attribute 属性、Skills 技能或 set 信息。</li><li>管理员通过命令发放物品。</li><li>玩家使用装备。</li><li>Item 在触发时机自动更新物品状态。</li><li>Forge / Strengthen / Gem 可继续在该物品上写入自己的 layer。</li><li>CoreLib 统一重建最终展示。</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>Item 写入基础属性或套装属性。</td></tr><tr><td>EmakiSkills</td><td>Item 写入装备技能 ID 与装备强制触发器；PDC 键由独立协议模块统一持有，不依赖 EmakiSkills 是否启用。</td></tr><tr><td>EmakiForge</td><td>Forge 可以改造 EmakiItem 生成的装备。</td></tr><tr><td>EmakiStrengthen</td><td>Strengthen 可以强化 EmakiItem 装备。</td></tr><tr><td>EmakiGem</td><td>Gem 可以给 EmakiItem 装备开孔和镶嵌。</td></tr><tr><td>MythicMobs</td><td>MythicMobs 怪物可以通过 <code>Drops</code> 掉落 EmakiItem 物品。</td></tr></tbody></table>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};